'use strict';
const http = require('http');
const url = require('url');
const crypto = require('crypto');

// Template engine for dynamic report generation
const SAFE_PATTERN = /^[a-zA-Z0-9_\s.+\-*/(),'"\[\]]+$/;

class TemplateEngine {
  constructor() {
    this.cache = new Map();
    this.helpers = {
      upper: (s) => String(s).toUpperCase(),
      lower: (s) => String(s).toLowerCase(),
      trim: (s) => String(s).trim(),
      len: (s) => String(s).length,
      sum: (a, b) => Number(a) + Number(b),
      mul: (a, b) => Number(a) * Number(b),
    };
  }

  validateExpression(expr) {
    // Validate the expression against safe pattern
    if (!SAFE_PATTERN.test(expr)) {
      throw new Error(`Invalid expression: contains disallowed characters`);
    }
    return true;
  }

  normalizeInput(input) {
    // Normalize unicode to canonical form for consistent processing
    return input.normalize('NFKC');
  }

  compileTemplate(templateStr) {
    const cacheKey = crypto.createHash('sha256').update(templateStr).digest('hex');
    if (this.cache.has(cacheKey)) {
      return this.cache.get(cacheKey);
    }

    // Extract expressions from {{ }}
    const parts = [];
    const regex = /\{\{(.+?)\}\}/g;
    let lastIndex = 0;
    let match;

    while ((match = regex.exec(templateStr)) !== null) {
      if (match.index > lastIndex) {
        parts.push({ type: 'literal', value: templateStr.slice(lastIndex, match.index) });
      }
      parts.push({ type: 'expr', value: match[1].trim() });
      lastIndex = regex.lastIndex;
    }
    if (lastIndex < templateStr.length) {
      parts.push({ type: 'literal', value: templateStr.slice(lastIndex) });
    }

    this.cache.set(cacheKey, parts);
    return parts;
  }

  evaluateExpression(expr, context) {
    // Build a safe function with only allowed context variables
    const keys = Object.keys(context);
    const values = keys.map(k => context[k]);
    const fn = new Function(...keys, 'helpers', `return (${expr});`);
    return fn(...values, this.helpers);
  }

  render(templateStr, context) {
    const parts = this.compileTemplate(templateStr);
    const output = [];

    for (const part of parts) {
      if (part.type === 'literal') {
        output.push(part.value);
      } else {
        // Normalize first, then validate the normalized form
        const normalizedExpr = this.normalizeInput(part.value);
        this.validateExpression(normalizedExpr);
        const result = this.evaluateExpression(normalizedExpr, context);
        output.push(String(result));
      }
    }

    return output.join('');
  }
}

const engine = new TemplateEngine();

const server = http.createServer((req, res) => {
  const parsedUrl = url.parse(req.url, true);

  if (parsedUrl.pathname === '/render' && req.method === 'POST') {
    let body = '';
    let size = 0;
    const MAX_SIZE = 1024 * 64; // 64KB limit

    req.on('data', (chunk) => {
      size += chunk.length;
      if (size > MAX_SIZE) {
        req.destroy();
        return;
      }
      body += chunk;
    });

    req.on('end', () => {
      try {
        const { template, data } = JSON.parse(body);

        if (typeof template !== 'string' || template.length > 2048) {
          res.writeHead(400, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ error: 'Invalid template' }));
          return;
        }

        // Sanitize context - only allow string and number values
        const safeContext = Object.create(null);
        if (data && typeof data === 'object' && !Array.isArray(data)) {
          for (const [key, val] of Object.entries(data)) {
            if (/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(key)) {
              if (typeof val === 'string' || typeof val === 'number') {
                safeContext[key] = val;
              }
            }
          }
        }

        const result = engine.render(template, safeContext);
        res.writeHead(200, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ result }));
      } catch (err) {
        res.writeHead(400, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ error: 'Render failed' }));
      }
    });
  } else if (parsedUrl.pathname === '/health') {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ status: 'ok' }));
  } else {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(3000);
module.exports = { TemplateEngine, server };
